#!/usr/bin/env python3
"""subtask1_generator.py

Deterministic JSONL event generator, validator and run logger.

The generator synthesises events that obey a lightweight JSON-Schema subset,
writes them as newline-delimited JSON (JSONL) and records every invocation in
``logs/gen.log``.  Two runs with identical arguments produce byte-identical
JSONL output because every synthesised value - including ids and timestamps -
is derived from the seed through a SHA-256 based pseudo random generator that
does not depend on the wall clock or on CPython's ``random`` implementation.

Usage
-----
    python3 subtask1_generator.py --seed 42 --count 20 \
        --schema domain/events.schema.json --mode overwrite \
        --out data/events.jsonl

    # Validate an existing stream without generating anything::
    python3 subtask1_generator.py --validate \
        --schema domain/events.schema.json --out data/events.jsonl

Only the Python standard library is used (Python 3.10+).
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import sys
import uuid
from datetime import datetime, timedelta, timezone

DEFAULT_SCHEMA = os.path.join("domain", "events.schema.json")
DEFAULT_OUT = os.path.join("data", "events.jsonl")
DEFAULT_LOG = os.path.join("logs", "gen.log")

# Stable namespace so that ``uuid5`` output never changes between runs.
ID_NAMESPACE = uuid.UUID("6ba7b811-9dad-11d1-80b4-00c04fd430c8")

# Fixed epoch: timestamps are offsets from this instant, never from "now".
EPOCH = datetime(2020, 1, 1, 0, 0, 0, tzinfo=timezone.utc)

_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


# ---------------------------------------------------------------------------
# Deterministic pseudo random generator (SHA-256 counter mode)
# ---------------------------------------------------------------------------
class DetRandom:
    """A tiny deterministic PRNG based on SHA-256.

    Values depend only on the seed and the draw order, which makes the output
    reproducible on any interpreter/platform and avoids relying on the
    implementation details of the stdlib ``random`` module.
    """

    def __init__(self, seed):
        self._seed = str(seed).encode("utf-8")
        self._counter = 0

    def _bytes(self, n):
        out = bytearray()
        while len(out) < n:
            digest = hashlib.sha256(
                self._seed + b":" + str(self._counter).encode("ascii")
            ).digest()
            self._counter += 1
            out.extend(digest)
        return bytes(out[:n])

    def rand_int(self, low, high):
        """Uniform integer in the inclusive range [low, high]."""
        if high < low:
            low, high = high, low
        span = high - low + 1
        value = int.from_bytes(self._bytes(8), "big")
        return low + (value % span)

    def rand_float(self, low, high, decimals=2):
        """Deterministic fixed-precision float in [low, high]."""
        scale = 10 ** decimals
        lo = int(round(low * scale))
        hi = int(round(high * scale))
        return self.rand_int(lo, hi) / float(scale)

    def choice(self, seq):
        seq = list(seq)
        return seq[self.rand_int(0, len(seq) - 1)]

    def token(self, min_len, max_len, alphabet):
        [secret redacted]
        return "".join(self.choice(alphabet) for _ in range(length))


# ---------------------------------------------------------------------------
# Synthesis of values that obey the schema
# ---------------------------------------------------------------------------
_LOWER = "abcdefghijklmnopqrstuvwxyz"
_TOKEN_CHARS = [secret redacted]


def _json_type(prop):
    t = prop.get("type")
    if isinstance(t, list):
        return t[0]
    return t


def synth_value(prop, rng):
    """Create a deterministic value satisfying ``prop`` (a schema fragment)."""
    if not isinstance(prop, dict):
        return None

    if "enum" in prop:
        return rng.choice(prop["enum"])

    typ = _json_type(prop)

    if typ == "string":
        fmt = prop.get("format")
        if fmt == "email":
            local = rng.token(4, 10, _LOWER)
            domain = rng.choice(["example.com", "example.org", "test.io"])
            return "%s@%s" % (local, domain)
        if fmt == "date-time":
            offset = rng.rand_int(0, 10 ** 7)
            return format_timestamp(offset)
        if fmt == "uuid":
            return str(uuid.uuid5(ID_NAMESPACE, "value:%d" % rng.rand_int(0, 10 ** 9)))
        if "pattern" in prop:
            # Support the common ``^[a-z][a-z0-9_]*$`` style pattern.
            min_len = max(prop.get("minLength", 3), 1)
            max_len = max(prop.get("maxLength", min_len), min_len)
            body = rng.token(min_len, max_len, _TOKEN_CHARS)
            body = rng.choice(_LOWER) + body[1:]
            return body
        min_len = prop.get("minLength", 1)
        max_len = prop.get("maxLength", max(min_len, 12))
        return rng.token(min_len, max_len, _LOWER)

    if typ == "integer":
        low = int(prop.get("minimum", 0))
        high = int(prop.get("maximum", low + 1000))
        return rng.rand_int(low, high)

    if typ == "number":
        low = float(prop.get("minimum", 0.0))
        high = float(prop.get("maximum", low + 1000.0))
        return rng.rand_float(low, high)

    if typ == "boolean":
        return rng.choice([True, False])

    if typ == "array":
        items = prop.get("items", {"type": "string"})
        low = int(prop.get("minItems", 0))
        high = int(prop.get("maxItems", max(low, low + 3)))
        n = rng.rand_int(low, high)
        unique = bool(prop.get("uniqueItems", False))
        out = []
        guard = 0
        while len(out) < n and guard < n * 20:
            guard += 1
            value = synth_value(items, rng)
            if unique and value in out:
                continue
            out.append(value)
        return out

    if typ == "object":
        return synth_object(prop, rng)

    return None


def synth_object(schema, rng):
    """Synthesise an object with every declared property (required ones first)."""
    props = schema.get("properties", {})
    required = schema.get("required", [])
    result = {}
    ordered = list(required) + [k for k in props if k not in required]
    for name in ordered:
        if name not in props:
            continue
        result[name] = synth_value(props[name], rng)
    return result


def format_timestamp(offset_seconds):
    return (EPOCH + timedelta(seconds=int(offset_seconds))).strftime(
        "%Y-%m-%dT%H:%M:%SZ"
    )


def generate_events(seed, count, schema):
    """Yield ``count`` deterministic event records obeying ``schema``."""
    rng = DetRandom(seed)
    props = schema.get("properties", {})
    base_offset = (abs(int(seed)) % 100000) * 3600

    records = []
    for index in range(count):
        record = {}
        for name, prop in props.items():
            if name == "id" and prop.get("format") == "uuid":
                record[name] = str(uuid.uuid5(ID_NAMESPACE, "%d:%d" % (seed, index)))
            elif name == "timestamp" and prop.get("format") == "date-time":
                record[name] = format_timestamp(base_offset + index)
            else:
                record[name] = synth_value(prop, rng)
        records.append(record)
    return records


# ---------------------------------------------------------------------------
# Built-in validator (lightweight JSON-Schema subset)
# ---------------------------------------------------------------------------
def _type_ok(value, typ):
    if typ == "object":
        return isinstance(value, dict)
    if typ == "array":
        return isinstance(value, list)
    if typ == "string":
        return isinstance(value, str)
    if typ == "boolean":
        return isinstance(value, bool)
    if typ == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if typ == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if typ == "null":
        return value is None
    return True


def validate_value(value, schema, path, errors):
    if not isinstance(schema, dict):
        return

    typ = _json_type(schema)
    if typ is not None and not _type_ok(value, typ):
        errors.append("%s: expected %s, got %s" % (path, typ, type(value).__name__))
        return

    if "enum" in schema and value not in schema["enum"]:
        errors.append("%s: value %r not in enum" % (path, value))
        return

    if isinstance(value, str):
        if "minLength" in schema and len(value) < schema["minLength"]:
            errors.append("%s: shorter than minLength" % path)
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            errors.append("%s: longer than maxLength" % path)
        if "pattern" in schema and not re.search(schema["pattern"], value):
            errors.append("%s: does not match pattern" % path)
        fmt = schema.get("format")
        if fmt == "uuid":
            try:
                uuid.UUID(value)
            except (ValueError, AttributeError, TypeError):
                errors.append("%s: not a valid uuid" % path)
        elif fmt == "date-time":
            try:
                datetime.fromisoformat(value.replace("Z", "+00:00"))
            except ValueError:
                errors.append("%s: not a valid date-time" % path)
        elif fmt == "email":
            if not _EMAIL_RE.match(value):
                errors.append("%s: not a valid email" % path)

    if isinstance(value, bool):
        pass
    elif isinstance(value, (int, float)):
        if "minimum" in schema and value < schema["minimum"]:
            errors.append("%s: below minimum" % path)
        if "maximum" in schema and value > schema["maximum"]:
            errors.append("%s: above maximum" % path)
        if "multipleOf" in schema and schema["multipleOf"]:
            multiple = schema["multipleOf"]
            if (value / multiple) != int(value / multiple):
                errors.append("%s: not a multipleOf" % path)

    if isinstance(value, list):
        if "minItems" in schema and len(value) < schema["minItems"]:
            errors.append("%s: fewer than minItems" % path)
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            errors.append("%s: more than maxItems" % path)
        if schema.get("uniqueItems"):
            seen = []
            for item in value:
                if item in seen:
                    errors.append("%s: duplicate items" % path)
                    break
                seen.append(item)
        items = schema.get("items")
        if isinstance(items, dict):
            for i, item in enumerate(value):
                validate_value(item, items, "%s[%d]" % (path, i), errors)

    if isinstance(value, dict):
        for key in schema.get("required", []):
            [secret redacted]
                errors.append("%s: missing required property %r" % (path, key))
        props = schema.get("properties", {})
        for key, sub in props.items():
            [secret redacted]
                validate_value(value[key], sub, "%s.%s" % (path, key), errors)
        if schema.get("additionalProperties") is False:
            for key in value:
                [secret redacted]
                    errors.append("%s: unexpected property %r" % (path, key))


def validate_record(record, schema):
    """Return a list of error strings for a single record ([] means valid)."""
    errors = []
    validate_value(record, schema, "$", errors)
    return errors


def validate_records(records, schema):
    """Return ``(valid_count, total, all_errors)`` for an iterable of records."""
    valid = 0
    errors = []
    total = 0
    for i, record in enumerate(records):
        total += 1
        rec_errors = validate_record(record, schema)
        if rec_errors:
            errors.append({"index": i, "errors": rec_errors})
        else:
            valid += 1
    return valid, total, errors


def validate_file(path, schema):
    records = read_jsonl(path)
    return validate_records(records, schema)


# ---------------------------------------------------------------------------
# JSONL I/O
# ---------------------------------------------------------------------------
def read_jsonl(path):
    records = []
    if not os.path.exists(path):
        return records
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return records


def encode_record(record):
    return json.dumps(record, sort_keys=[secret redacted]


def write_jsonl(path, records, mode="overwrite", dedup=True):
    """Write records to ``path``.

    ``overwrite`` replaces the file.  ``append`` is idempotent: records whose
    id already exists in the file are skipped, so re-running an identical
    invocation leaves the file byte-identical.

    Returns ``(appended, skipped)``.
    """
    directory = os.path.dirname(os.path.abspath(path))
    if directory:
        os.makedirs(directory, exist_ok=True)

    appended = 0
    skipped = 0

    if mode == "append" and os.path.exists(path):
        existing = read_jsonl(path)
        seen = {rec.get("id") for rec in existing if isinstance(rec, dict)}
        new_records = []
        for record in records:
            rid = record.get("id") if isinstance(record, dict) else None
            if dedup and rid is not None and rid in seen:
                skipped += 1
                continue
            new_records.append(record)
            if rid is not None:
                seen.add(rid)
        with open(path, "a", encoding="utf-8", newline="\n") as handle:
            for record in new_records:
                handle.write(encode_record(record) + "\n")
        appended = len(new_records)
    else:
        with open(path, "w", encoding="utf-8", newline="\n") as handle:
            for record in records:
                handle.write(encode_record(record) + "\n")
        appended = len(records)

    return appended, skipped


def sha256_file(path):
    digest = hashlib.sha256()
    if not os.path.exists(path):
        return None
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
def utc_now():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def append_log(log_path, entry):
    directory = os.path.dirname(os.path.abspath(log_path))
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(log_path, "a", encoding="utf-8", newline="\n") as handle:
        handle.write(json.dumps(entry, sort_keys=[secret redacted]


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------
def load_schema(path):
    with open(path, "r", encoding="utf-8") as handle:
        return json.load(handle)


def build_parser():
    parser = argparse.ArgumentParser(
        description="Deterministic JSONL event generator with built-in validator."
    )
    parser.add_argument("--seed", type=int, default=0, help="integer seed")
    parser.add_argument("--count", type=int, default=10, help="number of events")
    parser.add_argument(
        "--schema", default=DEFAULT_SCHEMA, help="path to JSON schema fragment"
    )
    parser.add_argument(
        "--mode",
        choices=["append", "overwrite"],
        default="append",
        help="append (idempotent) or overwrite the output file",
    )
    parser.add_argument("--out", default=DEFAULT_OUT, help="output JSONL path")
    parser.add_argument("--log", default=DEFAULT_LOG, help="path to the run log")
    parser.add_argument(
        "--validate",
        action="store_true",
        help="validate an existing --out file instead of generating",
    )
    parser.add_argument(
        "--quiet", action="store_true", help="suppress the stdout summary"
    )
    return parser


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)

    if args.count < 0:
        parser.error("--count must be non-negative")

    try:
        schema = load_schema(args.schema)
    except (OSError, json.JSONDecodeError) as exc:
        parser.error("could not load schema %r: %s" % (args.schema, exc))

    timestamp = utc_now()

    if args.validate:
        valid, total, errors = validate_file(args.out, schema)
        ratio = (valid / total) if total else 1.0
        summary = {
            "mode": "validate",
            "schema": args.schema,
            "out": args.out,
            "timestamp": timestamp,
            "valid": valid,
            "total": total,
            "ratio": round(ratio, 6),
        }
        append_log(args.log, summary)
        if not args.quiet:
            print(json.dumps(summary, sort_keys=[secret redacted]
        return 0

    records = generate_events(args.seed, args.count, schema)
    appended, skipped = write_jsonl(args.out, records, mode=args.mode)
    valid, total, errors = validate_file(args.out, schema)
    ratio = (valid / total) if total else 1.0
    digest = sha256_file(args.out)

    entry = {
        "timestamp": timestamp,
        "seed": args.seed,
        "count": args.count,
        "schema": args.schema,
        "mode": args.mode,
        "out": args.out,
        "appended": appended,
        "skipped": skipped,
        "total_records": total,
        "valid_records": valid,
        "valid_ratio": round(ratio, 6),
        "sha256": digest,
    }
    append_log(args.log, entry)

    if not args.quiet:
        print(
            "seed=%d count=%d mode=%s out=%s appended=%d skipped=%d "
            "valid=%d/%d sha256=%s"
            % (
                args.seed,
                args.count,
                args.mode,
                args.out,
                appended,
                skipped,
                valid,
                total,
                digest,
            )
        )
    return 0


if __name__ == "__main__":
    sys.exit(main())

