#!/usr/bin/env python3
"""Transactional, crash-safe key/value store (AgencyBench scenario3 subtask2).

Features
--------
* ``KVStore`` with ``begin_tx/put/get/commit/abort`` semantics.
* Snapshot-isolation style reads with write-write conflict detection
  (transactions that race on the same key never both commit -> no lost update).
* Append-only write-ahead log (``kv/wal.log``) with length + CRC32 framing so a
  torn / half-written trailing record is detected and ignored on recovery.
* Atomic binary snapshots (``kv/snapshot.bin``) written via temp file + replace.
* Crash recovery replays snapshot + WAL and is idempotent (records whose version
  is already covered by the snapshot are skipped).
* A line-delimited JSON socket server so remote clients can run transactions.
* CLI switchboard used by the evaluator: ``--test-recovery``,
  ``--run-serializable-tests``, ``--run-concurrency-sim``, ``--bench-latency``
  and ``--server``.

Python 3.10 stdlib only.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import socket
import socketserver
import struct
import sys
import tempfile
import threading
import time
import uuid
import zlib

# --------------------------------------------------------------------------- #
# Constants / on-disk formats
# --------------------------------------------------------------------------- #

KV_DIR_DEFAULT = "kv"
WAL_NAME = "wal.log"
SNAP_NAME = "snapshot.bin"
EVENTS_DEFAULT = os.path.join("data", "events.jsonl")
LOG_DIR_DEFAULT = "logs"
GEN_LOG_DEFAULT = os.path.join("logs", "gen.log")

WAL_MAGIC = b"KVWAL1\x00"
SNAP_MAGIC = b"KVSNAP1\x00"
MAX_RECORD = 64 * 1024 * 1024
LATENCY_TARGET_S = 0.05


def canonical_json(obj) -> str:
    """Stable, byte-reproducible JSON encoding."""
    return json.dumps(obj, sort_keys=[secret redacted]


def clamp(value: float, low: float = 0.0, high: float = 1.0) -> float:
    return max(low, min(high, value))


# --------------------------------------------------------------------------- #
# Errors
# --------------------------------------------------------------------------- #

class ConflictError(Exception):
    """Raised by ``KVStore.commit`` when a write-write conflict is detected."""


class TransactionError(Exception):
    """Raised when operating on an inactive / invalid transaction."""


# --------------------------------------------------------------------------- #
# WAL helpers
# --------------------------------------------------------------------------- #

class WAL:
    """Framed append-only log: [u32 len][payload][u32 crc32]."""

    MAGIC = WAL_MAGIC

    @staticmethod
    def encode(record: dict) -> bytes:
        payload = canonical_json(record).encode("utf-8")
        crc = zlib.crc32(payload) & 0xFFFFFFFF
        return struct.pack(">I", len(payload)) + payload + struct.pack(">I", crc)

    @staticmethod
    def read_records(path: str):
        """Return ``(records, valid_length)``.

        Parsing stops at the first torn / corrupt frame so a partially written
        trailing record (a crash-time half segment) is naturally ignored.
        """
        if not os.path.exists(path):
            return [], 0
        with open(path, "rb") as fh:
            blob = fh.read()
        pos = 0
        if blob.startswith(WAL_MAGIC):
            pos = len(WAL_MAGIC)
        records = []
        while pos + 8 <= len(blob):
            (length,) = struct.unpack(">I", blob[pos:pos + 4])
            if length == 0 or length > MAX_RECORD:
                break
            end = pos + 4 + length
            if end + 4 > len(blob):
                break  # incomplete payload -> torn write
            payload = blob[pos + 4:end]
            (crc,) = struct.unpack(">I", blob[end:end + 4])
            if (zlib.crc32(payload) & 0xFFFFFFFF) != crc:
                break  # corrupt frame -> stop replay here
            try:
                records.append(json.loads(payload.decode("utf-8")))
            except ValueError:
                break
            pos = end + 4
        return records, pos

    @staticmethod
    def append(fh, record: dict, fsync: bool = True) -> int:
        frame = WAL.encode(record)
        fh.write(frame)
        fh.flush()
        if fsync:
            os.fsync(fh.fileno())
        return len(frame)


# --------------------------------------------------------------------------- #
# Snapshot helpers
# --------------------------------------------------------------------------- #

def write_snapshot(path: str, data, key_versions, version, txn_count) -> None:
    body = json.dumps(
        {
            "data": data,
            "key_versions": [secret redacted]
            "version": version,
            "txn_count": txn_count,
        },
        sort_keys=[secret redacted]
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("utf-8")
    crc = zlib.crc32(body) & 0xFFFFFFFF
    blob = (
        SNAP_MAGIC
        + struct.pack(">Q", int(version))
        + struct.pack(">Q", len(body))
        + body
        + struct.pack(">I", crc)
    )
    directory = os.path.dirname(os.path.abspath(path))
    os.makedirs(directory, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=directory, prefix=".snap-", suffix=".tmp")
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(blob)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except OSError:
                pass


def read_snapshot(path: str):
    if not os.path.exists(path):
        return None
    with open(path, "rb") as fh:
        blob = fh.read()
    if not blob.startswith(SNAP_MAGIC):
        return None
    off = len(SNAP_MAGIC)
    if off + 16 + 4 > len(blob):
        return None
    (version,) = struct.unpack(">Q", blob[off:off + 8])
    (length,) = struct.unpack(">Q", blob[off + 8:off + 16])
    body_start = off + 16
    body_end = body_start + length
    if body_end + 4 > len(blob):
        return None
    body = blob[body_start:body_end]
    (crc,) = struct.unpack(">I", blob[body_end:body_end + 4])
    if (zlib.crc32(body) & 0xFFFFFFFF) != crc:
        return None
    try:
        obj = json.loads(body.decode("utf-8"))
    except ValueError:
        return None
    obj["version"] = int(obj.get("version", version))
    return obj


