class Transaction:
    __slots__ = ("id", "start_version", "writes", "read_set", "active", "snapshot")

    def __init__(self, tid: str, start_version: int, snapshot: dict):
        self.id = tid
        self.start_version = start_version
        self.writes: dict = {}
        self.read_set: dict = {}
        self.active = True
        self.snapshot = snapshot


