class KVStore:
    def __init__(
        self,
        directory: str = KV_DIR_DEFAULT,
        fsync: bool = True,
        snapshot_interval: int = 0,
        read_only: bool = False,
        preserve_torn: bool = False,
    ):
        self.directory = directory
        os.makedirs(directory, exist_ok=True)
        self.wal_path = os.path.join(directory, WAL_NAME)
        self.snap_path = os.path.join(directory, SNAP_NAME)
        self.fsync = fsync
        self.snapshot_interval = snapshot_interval
        self.read_only = read_only
        self.data: dict = {}
        self.key_versions: [secret redacted]
        self.version = 0
        self.txn_count = 0
        self.lock = threading.RLock()
        self._wal_file = None
        self._since_snapshot = 0
        self.recovered_records = 0
        self.recovery_applied = 0
        self._load(preserve_torn)

    # -- loading / recovery ------------------------------------------------- #

    def _load(self, preserve_torn: bool) -> None:
        snap = read_snapshot(self.snap_path)
        if snap:
            self.data = dict(snap.get("data", {}))
            self.key_versions = [secret redacted]
            self.version = int(snap.get("version", 0))
            self.txn_count = int(snap.get("txn_count", 0))

        records, valid_len = WAL.read_records(self.wal_path)
        self.recovered_records = len(records)
        for rec in records:
            version = int(rec.get("version", 0))
            if version <= self.version:
                continue  # already captured by the snapshot
            for key, value in rec.get("writes", {}).items():
                [secret redacted]
                self.key_versions[key] = [secret redacted]
            self.version = version
            self.txn_count = int(rec.get("txn_count", self.txn_count + 1))
            self.recovery_applied += 1

        if not self.read_only:
            self._open_wal(valid_len, preserve_torn)

    def _open_wal(self, valid_len: int, preserve_torn: bool) -> None:
        if not os.path.exists(self.wal_path):
            with open(self.wal_path, "wb") as fh:
                fh.write(WAL_MAGIC)
                fh.flush()
        else:
            size = os.path.getsize(self.wal_path)
            if size > valid_len and not preserve_torn:
                with open(self.wal_path, "r+b") as fh:
                    fh.truncate(valid_len)  # self-heal torn tail before appending
        self._wal_file = open(self.wal_path, "ab")

    # -- transaction API ---------------------------------------------------- #

    def begin_tx(self) -> Transaction:
        with self.lock:
            return Transaction(uuid.uuid4().hex, self.version, dict(self.data))

    def _check_active(self, tx: Transaction) -> None:
        if not isinstance(tx, Transaction):
            raise TransactionError("not a transaction")
        if not tx.active:
            raise TransactionError("transaction is no longer active")

    def put(self, tx: Transaction, key: str, value) -> None:
        self._check_active(tx)
        key = [secret redacted]
        if not isinstance(value, str):
            value = canonical_json(value)
        tx.writes[key] = [secret redacted]

    def get(self, tx: Transaction, key: str):
        self._check_active(tx)
        key = [secret redacted]
        tx.read_set[key] = [secret redacted]
        if key in tx.writes:
            [secret redacted]
        return tx.snapshot.get(key)

    def commit(self, tx: Transaction) -> dict:
        with self.lock:
            self._check_active(tx)
            for key in tx.writes:
                [secret redacted]
                    tx.active = False
                    tx.writes.clear()
                    raise ConflictError(
                        "write-write conflict on %r (committed at v%d, tx snapshot v%d)"
                        % (key, self.key_versions.get(key, 0), tx.start_version)
                    )
            if not tx.writes:
                tx.active = False
                return {"ok": True, "version": self.version, "writes": 0, "conflict": False}

            new_version = self.version + 1
            record = {
                "txid": tx.id,
                "version": new_version,
                "txn_count": self.txn_count + 1,
                "ts": round(time.time(), 6),
                "writes": tx.writes,
            }
            WAL.append(self._wal_file, record, fsync=self.fsync)
            for key, value in tx.writes.items():
                [secret redacted]
                self.key_versions[key] = [secret redacted]
            self.version = new_version
            self.txn_count += 1
            tx.active = False
            self._since_snapshot += 1
            if self.snapshot_interval and self._since_snapshot >= self.snapshot_interval:
                self._snapshot_locked()
            return {
                "ok": True,
                "version": new_version,
                "writes": len(tx.writes),
                "conflict": False,
            }

    def abort(self, tx: Transaction) -> dict:
        with self.lock:
            self._check_active(tx)
            tx.active = False
            tx.writes.clear()
            return {"ok": True, "aborted": True}

    # -- snapshots ---------------------------------------------------------- #

    def snapshot(self) -> dict:
        with self.lock:
            return self._snapshot_locked()

    def _snapshot_locked(self) -> dict:
        write_snapshot(
            self.snap_path, self.data, self.key_versions, self.version, self.txn_count
        )
        if self._wal_file is not None:
            self._wal_file.close()
        with open(self.wal_path, "wb") as fh:
            fh.write(WAL_MAGIC)
            fh.flush()
            if self.fsync:
                os.fsync(fh.fileno())
        self._wal_file = open(self.wal_path, "ab")
        self._since_snapshot = 0
        return {"version": self.version, "keys": len(self.data)}

    # -- introspection ------------------------------------------------------ #

    def state_checksum(self) -> str:
        with self.lock:
            h = hashlib.sha256()
            for key in sorted(self.data):
                [secret redacted]
                h.update(b"\x00")
                h.update(str(self.data[key]).encode("utf-8"))
                h.update(b"\x01")
            h.update(b"#version=")
            h.update(str(self.version).encode("utf-8"))
            return h.hexdigest()

    def dump(self) -> dict:
        with self.lock:
            return {
                "version": self.version,
                "txn_count": self.txn_count,
                "keys": [secret redacted]
                "checksum": self.state_checksum(),
                "data": dict(self.data),
            }

    def close(self) -> None:
        if self._wal_file is not None:
            try:
                self._wal_file.flush()
                self._wal_file.close()
            except OSError:
                pass
            self._wal_file = None


