class _KVHandler(socketserver.StreamRequestHandler):
    def handle(self) -> None:
        for raw in self.rfile:
            line = raw.strip()
            if not line:
                continue
            try:
                request = json.loads(line.decode("utf-8"))
            except ValueError:
                self._send({"ok": False, "error": "bad json"})
                continue
            response = self.server.dispatch(request)
            self._send(response)
            if response.get("_shutdown"):
                break

    def _send(self, obj: dict) -> None:
        self.wfile.write((canonical_json(obj) + "\n").encode("utf-8"))
        self.wfile.flush()


class KVSocketServer(socketserver.ThreadingTCPServer):
    allow_reuse_address = True
    daemon_threads = True

    def __init__(self, address, store: KVStore):
        self.store = store
        self.sessions: dict = {}
        self.slock = threading.Lock()
        super().__init__(address, _KVHandler)

    def dispatch(self, request: dict) -> dict:
        op = request.get("op")
        try:
            if op == "ping":
                return {"ok": True, "pong": True}
            if op == "begin":
                tx = self.store.begin_tx()
                with self.slock:
                    self.sessions[tx.id] = tx
                return {"ok": True, "txid": tx.id, "start_version": tx.start_version}
            if op == "put":
                tx = self._session(request)
                self.store.put(tx, request["key"], request.get("value"))
                return {"ok": True}
            if op == "get":
                tx = self._session(request)
                return {"ok": True, "value": self.store.get(tx, request["key"])}
            if op == "commit":
                tx = self._session(request)
                try:
                    result = self.store.commit(tx)
                except ConflictError as exc:
                    self._drop(request.get("txid"))
                    return {"ok": False, "conflict": True, "error": str(exc)}
                self._drop(request.get("txid"))
                result["ok"] = True
                return result
            if op == "abort":
                tx = self._session(request)
                result = self.store.abort(tx)
                self._drop(request.get("txid"))
                return result
            if op == "dump":
                return {"ok": True, "dump": self.store.dump()}
            return {"ok": False, "error": "unknown op %r" % (op,)}
        except TransactionError as exc:
            return {"ok": False, "error": str(exc)}
        except KeyError as exc:
            [secret redacted]

    def _session(self, request: dict) -> Transaction:
        txid = request.get("txid")
        with self.slock:
            tx = self.sessions.get(txid)
        if tx is None:
            raise TransactionError("unknown txid %r" % (txid,))
        return tx

    def _drop(self, txid) -> None:
        with self.slock:
            self.sessions.pop(txid, None)


