def synth_event(index: int) -> dict:
    return {
        "actor": "bench_actor_%02d" % (index % 10),
        "id": str(uuid.uuid5(uuid.NAMESPACE_URL, "event-%d" % index)),
        "payload": {"active": index % 2 == 0, "user_id": index + 1},
        "timestamp": "2020-01-01T00:00:00Z",
        "type": "user.created",
    }


def payload_for(events, index: int) -> dict:
    if events:
        return events[index % len(events)]
    return synth_event(index)


