def test_recovery(directory: str, fsync: bool, events, quiet: bool = False) -> dict:
    """Half-complete WAL + crash + restart, then prove state consistency."""
    import shutil

    if os.path.isdir(directory):
        for name in (WAL_NAME, SNAP_NAME):
            path = os.path.join(directory, name)
            if os.path.exists(path):
                os.remove(path)
    os.makedirs(directory, exist_ok=True)

    store = KVStore(directory, fsync=fsync, snapshot_interval=0)

    # Phase 1: committed transactions before the snapshot.
    for i in range(5):
        tx = store.begin_tx()
        store.put(tx, "event:%04d" % i, payload_for(events, i))
        store.put(tx, "counter:%02d" % (i % 3), str(i))
        store.commit(tx)

    snap_info = store.snapshot()  # writes snapshot.bin, rotates wal.log

    # Phase 2: transactions committed after the snapshot (live WAL tail).
    for i in range(5, 9):
        tx = store.begin_tx()
        store.put(tx, "event:%04d" % i, payload_for(events, i))
        store.put(tx, "counter:%02d" % (i % 3), str(i))
        store.commit(tx)

    expected_checksum = store.state_checksum()
    expected_version = store.version
    expected_keys = [secret redacted]

    # Phase 3: simulate a crash that leaves a HALF-COMPLETE WAL segment.
    pending = {
        "txid": "crash-pending",
        "version": store.version + 1,
        "txn_count": store.txn_count + 1,
        "ts": round(time.time(), 6),
        "writes": {"event:9999": payload_for(events, 9999), "half": "x" * 512},
    }
    frame = WAL.encode(pending)
    with open(store.wal_path, "ab") as fh:
        fh.write(frame[: max(1, len(frame) // 2)])  # truncate mid-record
        fh.flush()
        if fsync:
            os.fsync(fh.fileno())
    store.close()
    del store  # in-memory state is gone -- this is the "crash"

    # Phase 4: restart and recover from snapshot + WAL.
    recovered = KVStore(directory, fsync=fsync, read_only=True, preserve_torn=True)
    got_checksum = recovered.state_checksum()
    state_match = got_checksum == expected_checksum
    version_match = recovered.version == expected_version
    pending_absent = recovered.data.get("event:9999") is None
    ok = state_match and version_match and pending_absent

    result = {
        "recovery_ok": ok,
        "expected_checksum": expected_checksum,
        "recovered_checksum": got_checksum,
        "expected_version": expected_version,
        "recovered_version": recovered.version,
        "recovered_keys": [secret redacted]
        "expected_keys": [secret redacted]
        "wal_records_replayed": recovered.recovery_applied,
        "wal_records_seen": recovered.recovered_records,
        "half_complete_record_ignored": pending_absent,
        "checksum_match": state_match,
        "version_match": version_match,
        "snapshot": snap_info,
        "artifacts": {
            "wal": os.path.abspath(store.wal_path),
            "snapshot": os.path.abspath(store.snap_path),
        },
    }

    if not quiet:
        print("recovery wal_records_seen=%d wal_records_replayed=%d"
              % (result["wal_records_seen"], result["wal_records_replayed"]))
        print("recovery expected_checksum=%s" % expected_checksum)
        print("recovery recovered_checksum=%s" % got_checksum)
        print("recovery version expected=%d recovered=%d"
              % (expected_version, recovered.version))
        print("recovery keys expected=[secret redacted]
              % (expected_keys, len(recovered.data)))
        print("RECOVERY SUCCESS" if ok else "RECOVERY FAILURE")
    result["status"] = "RECOVERY SUCCESS" if ok else "RECOVERY FAILURE"
    return result


