def run_serializable_tests(events, fsync: bool) -> dict:
    root = tempfile.mkdtemp(prefix="kv-serial-")
    counter = {"n": 0}

    def new_store() -> KVStore:
        counter["n"] += 1
        return KVStore(os.path.join(root, "store%d" % counter["n"]), fsync=False)

    def t_read_your_writes() -> bool:
        kv = new_store()
        tx = kv.begin_tx()
        kv.put(tx, "a", "1")
        ok = kv.get(tx, "a") == "1"
        kv.abort(tx)
        return ok

    def t_uncommitted_invisible() -> bool:
        kv = new_store()
        tx1 = kv.begin_tx()
        kv.put(tx1, "a", "1")
        tx2 = kv.begin_tx()
        ok = kv.get(tx2, "a") is None
        kv.abort(tx1)
        kv.abort(tx2)
        return ok

    def t_commit_visible() -> bool:
        kv = new_store()
        tx = kv.begin_tx()
        kv.put(tx, "a", "1")
        kv.commit(tx)
        tx2 = kv.begin_tx()
        return kv.get(tx2, "a") == "1"

    def t_abort_discards() -> bool:
        kv = new_store()
        tx = kv.begin_tx()
        kv.put(tx, "a", "1")
        kv.abort(tx)
        tx2 = kv.begin_tx()
        return kv.get(tx2, "a") is None

    def t_write_write_conflict() -> bool:
        kv = new_store()
        t1 = kv.begin_tx()
        t2 = kv.begin_tx()
        kv.put(t1, "a", "1")
        kv.put(t2, "a", "2")
        kv.commit(t1)
        try:
            kv.commit(t2)
            return False
        except ConflictError:
            return True

    def t_repeatable_read() -> bool:
        kv = new_store()
        setup = kv.begin_tx()
        kv.put(setup, "a", "1")
        kv.commit(setup)
        tx1 = kv.begin_tx()
        first = kv.get(tx1, "a")
        tx2 = kv.begin_tx()
        kv.put(tx2, "a", "2")
        kv.commit(tx2)
        second = kv.get(tx1, "a")
        kv.abort(tx1)
        return first == "1" and second == "1"

    def t_no_lost_update() -> bool:
        kv = new_store()
        setup = kv.begin_tx()
        kv.put(setup, "counter", "0")
        kv.commit(setup)
        t1 = kv.begin_tx()
        t2 = kv.begin_tx()
        v1 = int(kv.get(t1, "counter"))
        v2 = int(kv.get(t2, "counter"))
        kv.put(t1, "counter", str(v1 + 1))
        kv.put(t2, "counter", str(v2 + 1))
        kv.commit(t1)
        try:
            kv.commit(t2)
            return False
        except ConflictError:
            pass
        check = kv.begin_tx()
        final = kv.get(check, "counter")
        kv.abort(check)
        return final == "1"

    def t_multi_key_atomic_commit() -> bool:
        [secret redacted]
        tx = kv.begin_tx()
        for k in ("a", "b", "c"):
            kv.put(tx, k, k.upper())
        kv.commit(tx)
        check = kv.begin_tx()
        ok = all(kv.get(check, k) == k.upper() for k in ("a", "b", "c"))
        kv.abort(check)
        return ok

    def t_abort_is_atomic() -> bool:
        kv = new_store()
        tx = kv.begin_tx()
        kv.put(tx, "a", "1")
        kv.put(tx, "b", "2")
        kv.abort(tx)
        check = kv.begin_tx()
        ok = kv.get(check, "a") is None and kv.get(check, "b") is None
        kv.abort(check)
        return ok

    def t_version_monotonic() -> bool:
        kv = new_store()
        v0 = kv.version
        tx = kv.begin_tx()
        kv.put(tx, "a", "1")
        result = kv.commit(tx)
        return result["version"] == v0 + 1 and kv.version == v0 + 1

    def t_concurrent_disjoint_commit() -> bool:
        kv = new_store()
        outcomes = []
        lock = threading.Lock()

        def worker(i):
            tx = kv.begin_tx()
            kv.put(tx, "k%02d" % i, str(i))
            res = kv.commit(tx)
            with lock:
                outcomes.append(res["ok"])

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(8)]
        for th in threads:
            th.start()
        for th in threads:
            th.join()
        return len(outcomes) == 8 and all(outcomes)

    def t_read_set_tracked() -> bool:
        kv = new_store()
        tx = kv.begin_tx()
        kv.get(tx, "missing")
        tracked = "missing" in tx.read_set
        kv.abort(tx)
        return tracked

    cases = [
        ("read_your_writes", t_read_your_writes),
        ("uncommitted_invisible", t_uncommitted_invisible),
        ("commit_visible", t_commit_visible),
        ("abort_discards", t_abort_discards),
        ("write_write_conflict", t_write_write_conflict),
        ("repeatable_read", t_repeatable_read),
        ("no_lost_update", t_no_lost_update),
        ("multi_key_atomic_commit", t_multi_key_atomic_commit),
        ("abort_is_atomic", t_abort_is_atomic),
        ("version_monotonic", t_version_monotonic),
        ("concurrent_disjoint_commit", t_concurrent_disjoint_commit),
        ("read_set_tracked", t_read_set_tracked),
    ]

    passed = 0
    details = []
    for name, fn in cases:
        try:
            ok = bool(fn())
        except Exception as exc:  # noqa: BLE001 - report, do not crash the suite
            ok = False
            details.append({"test": name, "passed": False, "error": repr(exc)})
        else:
            details.append({"test": name, "passed": ok})
        passed += int(ok)

    total = len(cases)
    return {
        "serializable_tests_passed": passed,
        "total_serializable_tests": total,
        "ratio": passed / total if total else 0.0,
        "details": details,
    }


