def run_concurrency_sim(
    events,
    clients: int = 8,
    txns_per_client: int = 15,
    fsync: bool = False,
) -> dict:
    directory = tempfile.mkdtemp(prefix="kv-concurrency-")
    store = KVStore(directory, fsync=fsync, snapshot_interval=0)
    server = KVSocketServer(("127.0.0.1", 0), store)
    host, port = server.server_address[0], server.server_address[1]
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()

    total = clients * txns_per_client
    results = {"success": 0, "conflict": 0, "error": 0, "first_attempt_success": 0}
    lock = threading.Lock()

    def rpc(sock_file, sock, obj):
        sock_file.write((canonical_json(obj) + "\n").encode("utf-8"))
        sock_file.flush()
        line = sock_file.readline()
        if not line:
            raise ConnectionError("server closed connection")
        return json.loads(line.decode("utf-8"))

    def worker(client_index: int) -> None:
        sock = socket.create_connection((host, port), timeout=10)
        sock_file = sock.makefile("rwb")
        namespace = "client%03d" % client_index
        local = {"success": 0, "conflict": 0, "error": 0, "first": 0}
        try:
            for j in range(txns_per_client):
                attempts = 0
                while True:
                    attempts += 1
