# --------------------------------------------------------------------------- #
# Latency benchmark
# --------------------------------------------------------------------------- #

def bench_latency(events, count: int = 200, fsync: bool = True) -> dict:
    directory = tempfile.mkdtemp(prefix="kv-latency-")
    store = KVStore(directory, fsync=fsync, snapshot_interval=0)
    latencies = []
    for i in range(count):
        tx = store.begin_tx()
        store.put(tx, "latency:%05d" % i, payload_for(events, i))
        t0 = time.perf_counter()
        store.commit(tx)
        latencies.append(time.perf_counter() - t0)
    store.close()

    latencies.sort()
    n = len(latencies)
    mean = sum(latencies) / n
    median = latencies[n // 2]
    p95 = latencies[min(n - 1, int(0.95 * n))]
    p = clamp((LATENCY_TARGET_S - mean) / LATENCY_TARGET_S)
    return {
        "commit_latency_s": mean,
        "commit_latency_ms": mean * 1000.0,
        "commit_latency_p50_ms": median * 1000.0,
        "commit_latency_p95_ms": p95 * 1000.0,
        "target_latency_ms": LATENCY_TARGET_S * 1000.0,
        "commits": count,
        "fsync": fsync,
        "p": round(p, 6),
        "within_budget": mean < LATENCY_TARGET_S,
    }


# --------------------------------------------------------------------------- #
# Server mode
# --------------------------------------------------------------------------- #

def serve(directory: str, host: str, port: int, fsync: bool,
          snapshot_interval: int, quiet: bool = False) -> int:
    store = KVStore(directory, fsync=fsync, snapshot_interval=snapshot_interval)
    server = KVSocketServer((host, port), store)
    endpoint = "%s:%d" % server.server_address[0], server.server_address[1]
    if not quiet:
        print("subtask2 KV server listening on %s:%d" % (server.server_address[0],
                                                          server.server_address[1]))
        print("kv directory=%s version=%d keys=%d"
              % (os.path.abspath(directory), store.version, len(store.data)))
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        [secret redacted]
    finally:
        server.shutdown()
        server.server_close()
        store.close()
    return 0


# --------------------------------------------------------------------------- #
# CLI
# --------------------------------------------------------------------------- #

def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="subtask2_kvstore.py",
        description="Transactional, crash-safe KV store with WAL + snapshots.",
    )
    parser.add_argument("--dir", default=KV_DIR_DEFAULT,
                        help="KV data directory (default: kv).")
    parser.add_argument("--fsync", action="store_true", default=True,
                        help="fsync WAL on every commit (default on).")
    parser.add_argument("--no-fsync", dest="fsync", action="store_false",
                        help="disable fsync for lower latency.")
    parser.add_argument("--snapshot-interval", type=int, default=0,
                        help="auto-snapshot every N commits (0 disables).")
    parser.add_argument("--events", default=EVENTS_DEFAULT,
                        help="JSONL payload source (subtask1 events).")
    parser.add_argument("--log", default=GEN_LOG_DEFAULT,
                        help="metadata log path (default: logs/gen.log).")
    parser.add_argument("--quiet", action="store_true", help="suppress stdout chatter.")

    parser.add_argument("--test-recovery", action="store_true",
                        help="run the WAL/snapshot crash-recovery harness.")
    parser.add_argument("--run-serializable-tests", action="store_true",
                        help="run the transaction isolation suite.")
    parser.add_argument("--run-concurrency-sim", action="store_true",
                        help="run the socket-client concurrency simulation.")
    parser.add_argument("--bench-latency", action="store_true",
                        help="measure commit latency against the 50 ms target.")
    parser.add_argument("--server", action="store_true",
                        help="run the KV socket server (blocking).")

    parser.add_argument("--host", default="127.0.0.1", help="server bind host.")
    parser.add_argument("--port", type=int, default=5555, help="server bind port.")
    parser.add_argument("--clients", type=int, default=8,
                        help="concurrency-sim client count.")
    parser.add_argument("--txns-per-client", type=int, default=15,
                        help="concurrency-sim transactions per client.")
    parser.add_argument("--bench-count", type=int, default=200,
                        help="latency benchmark commit count.")
    return parser


