        exit_code |= 0 if result["recovery_ok"] else 1

    if args.run_serializable_tests:
        did_something = True
        result = run_serializable_tests(events, args.fsync)
        log_event(args.log, {
            "task": "subtask2", "action": "run_serializable_tests",
            "serializable_tests_passed": result["serializable_tests_passed"],
            "total_serializable_tests": result["total_serializable_tests"],
            "ratio": result["ratio"],
        })
        print("serializable_tests_passed=%d total_serializable_tests=%d"
              % (result["serializable_tests_passed"], result["total_serializable_tests"]))
        _emit(result, args.quiet)

    if args.run_concurrency_sim:
        did_something = True
        result = run_concurrency_sim(events, clients=args.clients,
                                     txns_per_client=args.txns_per_client,
                                     fsync=args.fsync)
        log_event(args.log, {
            "task": "subtask2", "action": "run_concurrency_sim",
            "socket_client_trials_without_conflict": result["socket_client_trials_without_conflict"],
            "total_client_trials": result["total_client_trials"],
            "observed_conflicts": result["observed_conflicts"],
            "ratio": result["ratio"],
        })
        print("socket_client_trials_without_conflict=%d total_client_trials=%d"
              % (result["socket_client_trials_without_conflict"],
                 result["total_client_trials"]))
        _emit(result, args.quiet)

    if args.bench_latency:
        did_something = True
        result = bench_latency(events, count=args.bench_count, fsync=args.fsync)
        log_event(args.log, {
            "task": "subtask2", "action": "bench_latency",
            "commit_latency_ms": result["commit_latency_ms"],
            "target_latency_ms": result["target_latency_ms"],
