              % (result["commit_latency_ms"], result["target_latency_ms"], result["p"]))
        _emit(result, args.quiet)

    if args.server:
        did_something = True
        exit_code = serve(args.dir, args.host, args.port, args.fsync,
                          args.snapshot_interval, quiet=args.quiet)

    if not did_something:
        parser.print_help()
        return 2
    return exit_code


if __name__ == "__main__":
