#!/usr/bin/env python3
"""Automatic symbolic planner for AgencyBench scenario3 subtask4.

The planner consumes a STRIPS-style domain (operator JSON) and a problem/goal
JSON, decomposes the goal into a dependency DAG, searches for a feasible plan
(A* with an unsatisfied-goal-literals heuristic) and "submits" the resulting
tasks to a local queue (optionally persisted through the subtask2 KV store or
forwarded to a subtask3-style TCP orchestrator).

It writes a metrics report containing the five required grading keys
(``success_rate``, ``plan_length``, ``nodes_expanded``, ``heuristic_cost``,
``schedule_latency``) and exports the plan DAG for structural validation.

CLI::

    python3 subtask4_planner.py \
        --domain domain/operators.json \
        --goal domain/goal.json \
        --report reports/planner_report.json \
        --plan-export reports/plan_export.json

Python 3.10 standard library only.
"""

from __future__ import annotations

import argparse
import heapq
import itertools
import json
import os
import sys
import time

REQUIRED_METRIC_KEYS = [secret redacted]
    "success_rate",
    "plan_length",
    "nodes_expanded",
    "heuristic_cost",
    "schedule_latency",
]

DEFAULT_DOMAIN = os.path.join("domain", "operators.json")
DEFAULT_GOAL = os.path.join("domain", "goal.json")
DEFAULT_REPORT = os.path.join("reports", "planner_report.json")
DEFAULT_EXPORT = os.path.join("reports", "plan_export.json")
DEFAULT_LOG = os.path.join("logs", "orchestrator.log")


# --------------------------------------------------------------------------- #
# Small helpers
# --------------------------------------------------------------------------- #
def canonical_json(obj) -> str:
    """Deterministic compact JSON (sorted keys, ASCII, no spaces)."""
    return json.dumps(obj, sort_keys=[secret redacted]


def clamp(value, low: float = 0.0, high: float = 1.0) -> float:
    try:
        value = float(value)
    except (TypeError, ValueError):
        return float(low)
    if value < low:
        return float(low)
    if value > high:
        return float(high)
    return value


def ensure_parent(path: str) -> None:
    parent = os.path.dirname(os.path.abspath(path))
    if parent:
        os.makedirs(parent, exist_ok=True)


def load_json(path: str):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def parse_literal(text: str):
    """Parse ``pred(a,b)`` or ``pred`` into ``("pred", ("a", "b"))``."""
    if isinstance(text, (list, tuple)) and len(text) == 2:
        return (str(text[0]), tuple(str(a) for a in text[1]))
    text = str(text).strip()
    if not text:
        return None
    if text.startswith("(not ") and text.endswith(")"):
        return None  # negative literals are ignored (closed-world assumption)
    if "(" in text and text.endswith(")"):
        pred = text[: text.index("(")].strip()
        inner = text[text.index("(") + 1 : -1]
        args = tuple(a.strip() for a in inner.split(",") if a.strip())
        return (pred, args)
    return (text, ())


def format_literal(lit) -> str:
    pred, args = lit
    if args:
        return "%s(%s)" % (pred, ",".join(args))
    return pred


def _as_param_list(raw) -> list:
    """Normalise operator params to a list of ``[name, type]`` pairs."""
    out = []
    if isinstance(raw, dict):
        for name, ptype in raw.items():
            out.append([str(name), str(ptype)])
    elif isinstance(raw, (list, tuple)):
        for item in raw:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                out.append([str(item[0]), str(item[1])])
            else:
                out.append([str(item), "object"])
    return out


# --------------------------------------------------------------------------- #
# Domain / problem normalisation
# --------------------------------------------------------------------------- #
def normalise_domain(domain: dict) -> dict:
    ops = []
    for raw in domain.get("operators", []):
        params = _as_param_list(raw.get("params", []))
        add = raw.get("add", raw.get("effects", [])) or []
        delete = raw.get("delete", raw.get("del", [])) or []
        ops.append(
            {
                "name": str(raw["name"]),
                "params": params,
                "preconditions": [parse_literal(p) for p in raw.get("preconditions", [])],
                "add": [parse_literal(p) for p in add],
                "delete": [parse_literal(p) for p in delete],
                "neq": [tuple(pair) for pair in raw.get("neq", []) or []],
                "cost": int(raw.get("cost", 1)),
            }
        )
    ops.sort(key=[secret redacted]
    return {"name": str(domain.get("name", "domain")), "operators": ops}


def normalise_problem(problem: dict) -> dict:
    raw_objects = problem.get("objects", {}) or {}
    objects: dict = {}
    if isinstance(raw_objects, dict):
        for otype, names in raw_objects.items():
            objects[str(otype)] = [str(n) for n in names]
    elif isinstance(raw_objects, (list, tuple)):
        objects["object"] = [str(n) for n in raw_objects]

    init = [parse_literal(p) for p in problem.get("init", []) or []]
    goals = problem.get("goal", problem.get("goals", [])) or []
    if isinstance(goals, str):
        goals = [goals]
    goals = [parse_literal(g) for g in goals]

    return {
        "name": str(problem.get("name", "problem")),
        "objects": objects,
        "init": frozenset(l for l in init if l),
        "goals": tuple(l for l in goals if l),
    }


def domain_for_type(objects: dict, ptype: str) -> list:
    if ptype in objects:
        return sorted(objects[ptype])
    if "object" in objects:
        return sorted(objects["object"])
    # fall back to the union of every decorated type
    every = sorted({c for names in objects.values() for c in names})
    return every


def ground_operators(domain: dict, problem: dict) -> list:
    """Instantiate every operator over the problem objects."""
    objects = problem["objects"]
    grounded = []
    for op in domain["operators"]:
        domains = [domain_for_type(objects, p[1]) for p in op["params"]]
        if any(len(d) == 0 for d in domains):
            continue
        for combo in itertools.product(*domains):
            binding = {op["params"][i][0]: combo[i] for i in range(len(combo))}
            if any(binding.get(a) == binding.get(b) for a, b in op["neq"]):
                continue
            subst = lambda lit: (lit[0], tuple(binding.get(a, a) for a in lit[1]))
            grounded.append(
                {
                    "name": op["name"],
                    "params": tuple(combo),
                    "binding": binding,
                    "pre": frozenset(subst(l) for l in op["preconditions"]),
                    "add": frozenset(subst(l) for l in op["add"]),
                    "del": frozenset(subst(l) for l in op["delete"]),
                    "cost": op["cost"],
                    "label": "%s(%s)" % (op["name"], ",".join(combo)),
                }
            )
    grounded.sort(key=[secret redacted]
    return grounded


# --------------------------------------------------------------------------- #
# Search
# --------------------------------------------------------------------------- #
def heuristic(state, goals) -> int:
    return sum(1 for g in goals if g not in state)


def astar(actions, init, goals, max_expansions: int = 200000):
    """Return ``(plan, nodes_expanded, reached_goal, initial_h)``."""
    init_state = frozenset(init)
    initial_h = heuristic(init_state, goals)
    if initial_h == 0:
        return [], 0, True, 0

    counter = itertools.count()
    start_key = [secret redacted]
    best_g = {init_state: 0}
    came_from = {}
    came_action = {}
    open_heap = [(initial_h, 0, next(counter), start_key, init_state)]
    expanded = 0
    closed = set()

    while open_heap:
        f, g, _, key, state = [secret redacted]
        if state in closed:
            continue
        closed.add(state)
        expanded += 1
        if expanded > max_expansions:
            break
        if all(goal in state for goal in goals):
            # reconstruct
            plan = []
            cur = state
            while cur in came_from:
                act = came_action[cur]
                plan.append(act)
                cur = came_from[cur]
            plan.reverse()
            return plan, expanded, True, initial_h

        for act in actions:
            if not act["pre"] <= state:
                continue
            nxt = (state - act["del"]) | act["add"]
            if nxt == state:
                continue
            ng = g + act["cost"]
            if ng < best_g.get(nxt, 1 << 30):
                best_g[nxt] = ng
                came_from[nxt] = state
                came_action[nxt] = act
                nh = heuristic(nxt, goals)
                heapq.heappush(
                    open_heap, (ng + nh, ng, next(counter), tuple(sorted(nxt)), nxt)
                )
    return [], expanded, False, initial_h


# --------------------------------------------------------------------------- #
# Dependency DAG construction & validation
# --------------------------------------------------------------------------- #
def build_plan_dag(plan, init, goals):
    """Build a dependency DAG for a linear plan (causal + precedence edges)."""
    init = frozenset(init)
    nodes = []
    for i, act in enumerate(plan):
        nodes.append(
            {
                "id": "a%d" % i,
                "index": i,
                "operator": act["name"],
                "params": list(act["params"]),
                "label": act["label"],
            }
        )

    edge_set = {}  # (from_idx, to_idx) -> type

    for i, act in enumerate(plan):
        for pre in sorted(act["pre"]):
            if pre in init:
                continue
            producer = None
            for j in range(i - 1, -1, -1):
                if pre in plan[j]["add"]:
                    blocked = any(pre in plan[k]["del"] for k in range(j + 1, i))
                    if not blocked:
                        producer = j
                    break
            if producer is not None:
                edge_set.setdefault((producer, i), "causal")

    for i in range(len(plan) - 1):
        edge_set.setdefault((i, i + 1), "precedence")

    edges = [
        {"from": "a%d" % a, "to": "a%d" % b, "type": t}
        for (a, b), t in sorted(edge_set.items())
    ]

    # goal decomposition: which node first achieves each goal literal
    goal_sources = {}
    for goal in goals:
        glit = format_literal(goal)
        source = None
        if goal not in init:
            for i, act in enumerate(plan):
                if goal in act["add"]:
                    source = "a%d" % i
                    break
        goal_sources[glit] = source

    incoming = {n["id"]: 0 for n in nodes}
    outgoing = {n["id"]: 0 for n in nodes}
    for e in edges:
        if e["from"] in incoming and e["to"] in incoming:
            outgoing[e["from"]] += 1
            incoming[e["to"]] += 1
    roots = sorted(nid for nid, c in incoming.items() if c == 0)
    leaves = sorted(nid for nid, c in outgoing.items() if c == 0)

    return {
        "nodes": nodes,
        "edges": edges,
        "roots": roots,
        "leaves": leaves,
        "goal_sources": goal_sources,
    }


def validate_dag(dag) -> dict:
    """Validate that every edge references existing nodes and the graph is acyclic."""
    ids = {n["id"] for n in dag["nodes"]}
    total = len(dag["edges"])
    valid = 0
    adjacency = {nid: [] for nid in ids}
    invalid_edges = []
    for e in dag["edges"]:
        if e["from"] in ids and e["to"] in ids and e["from"] != e["to"]:
            valid += 1
            adjacency[e["from"]].append(e["to"])
        else:
            invalid_edges.append(e)

    # cycle check (DFS colouring)
    colour = {nid: 0 for nid in ids}
    acyclic = True

    def dfs(u):
        nonlocal acyclic
        colour[u] = 1
        for v in adjacency[u]:
            if colour[v] == 1:
                acyclic = False
            elif colour[v] == 0:
                dfs(v)
        colour[u] = 2

    for nid in sorted(ids):
        if colour[nid] == 0:
            dfs(nid)

    ratio = clamp(valid / total) if total else 1.0
    return {
        "valid_edges": valid,
        "total_edges": total,
        "invalid_edges": invalid_edges,
        "is_dag": bool(acyclic),
        "dag_validity": ratio,
        "node_count": len(ids),
    }


# --------------------------------------------------------------------------- #
# Task submission
# --------------------------------------------------------------------------- #
def submit_tasks(plan, dag, kv_dir: str, submit_mode: str, orchestrator: str, log_path: str):
    """Submit planned tasks; returns a submission summary.

    Modes: ``local`` (in-process queue), ``kv`` (also persist via subtask2),
    ``tcp`` (also forward to a host:port orchestrator), ``none``.
    """
    tasks = []
    for node in dag["nodes"]:
        tasks.append(
            {
                "task_id": "task-%s" % node["id"],
                "plan_node": node["id"],
                "operator": node["operator"],
                "params": node["params"],
                "label": node["label"],
                "status": "submitted",
            }
        )

    summary = {
        "submit_mode": submit_mode,
        "tasks_submitted": len(tasks),
        "durable": False,
        "remote": False,
        "errors": [],
    }

    if submit_mode == "kv":
        try:
            import subtask2_kvstore as kvmod  # local sibling module

            store = kvmod.KVStore(kv_dir, fsync=False)
            tx = store.begin_tx()
            for t in tasks:
                store.put(tx, "plan:%s" % t["task_id"], t)
            store.put(tx, "plan:meta", {"tasks": len(tasks), "labels": [t["label"] for t in tasks]})
            store.commit(tx)
            store.snapshot()
            store.close()
            summary["durable"] = True
        except Exception as exc:  # pragma: no cover - defensive
            summary["errors"].append("kv:%s" % exc)

    if submit_mode == "tcp" and orchestrator:
        try:
            import socket

            host, _, port = orchestrator.partition(":")
            port = int(port) if port else 5555
            with socket.create_connection((host, port), timeout=2.0) as sock:
                for t in tasks:
                    sock.sendall((canonical_json({"op": "submit", "task": t}) + "\n").encode("utf-8"))
            summary["remote"] = True
        except Exception as exc:  # pragma: no cover - defensive
            summary["errors"].append("tcp:%s" % exc)

    # append an orchestrator log line describing the submission
    try:
        ensure_parent(log_path)
        entry = {
            "action": "plan_submitted",
            "submit_mode": submit_mode,
            "tasks": len(tasks),
            "labels": [t["label"] for t in tasks],
            "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        with open(log_path, "a", encoding="utf-8") as fh:
            fh.write(canonical_json(entry) + "\n")
    except OSError:
        pass

    return tasks, summary


# --------------------------------------------------------------------------- #
# Orchestration
# --------------------------------------------------------------------------- #
def run_planner(
    domain_path: str,
    goal_path: str,
    report_path: str,
    export_path: str,
    kv_dir: str = "kv",
    submit_mode: str = "local",
    orchestrator: str = "",
    log_path: str = DEFAULT_LOG,
    max_expansions: int = 200000,
) -> dict:
    started = time.perf_counter()

    domain = normalise_domain(load_json(domain_path))
    problem = normalise_problem(load_json(goal_path))
    actions = ground_operators(domain, problem)

    plan, expanded, reached, initial_h = astar(
        actions, problem["init"], problem["goals"], max_expansions
    )

    dag = build_plan_dag(plan, problem["init"], problem["goals"])
    dag_check = validate_dag(dag)

    tasks, submission = submit_tasks(
        plan, dag, kv_dir, submit_mode, orchestrator, log_path
    )

    total_goals = len(problem["goals"])
    goals_satisfied = sum(1 for g in problem["goals"] if g in problem["init"]) + sum(
        1 for g in problem["goals"] if any(g in a["add"] and a in plan for a in plan)
    )
    # recompute precisely by replaying the plan
    state = set(problem["init"])
    for act in plan:
        state = (state - set(act["del"])) | set(act["add"])
    goals_satisfied = sum(1 for g in problem["goals"] if g in state)
    success_rate = clamp(goals_satisfied / total_goals) if total_goals else 1.0

    schedule_latency = time.perf_counter() - started

    plan_success = bool(reached and success_rate >= 1.0)
    heuristic_cost = initial_h + sum(heuristic(frozenset(), ()) for _ in ())

    report = {
        "success_rate": round(success_rate, 6),
        "plan_length": len(plan),
        "nodes_expanded": int(expanded),
        "heuristic_cost": int(initial_h),
        "schedule_latency": round(schedule_latency, 6),
        "plan_success": plan_success,
        "goals_total": total_goals,
        "goals_satisfied": goals_satisfied,
        "actions": [a["label"] for a in plan],
        "ground_actions": len(actions),
        "tasks_submitted": submission["tasks_submitted"],
        "submission": submission,
        "dag": {
            "nodes": len(dag["nodes"]),
            "edges": len(dag["edges"]),
            "valid_edges": dag_check["valid_edges"],
            "total_edges": dag_check["total_edges"],
            "is_dag": dag_check["is_dag"],
            "validity": round(dag_check["dag_validity"], 6),
        },
        "domain": os.path.abspath(domain_path),
        "goal": os.path.abspath(goal_path),
        "goal_name": problem["name"],
        "domain_name": domain["name"],
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    }

    export = {
        "plan_id": "plan:%s" % problem["name"],
        "domain": domain["name"],
        "problem": problem["name"],
        "success": plan_success,
        "plan_length": len(plan),
        "actions": [a["label"] for a in plan],
        "nodes": dag["nodes"],
        "edges": dag["edges"],
        "roots": dag["roots"],
        "leaves": dag["leaves"],
        "goal_sources": dag["goal_sources"],
        "validation": dag_check,
    }

    ensure_parent(report_path)
    ensure_parent(export_path)
    with open(report_path, "w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2, sort_keys=True)
        fh.write("\n")
    with open(export_path, "w", encoding="utf-8") as fh:
        json.dump(export, fh, indent=2, sort_keys=True)
        fh.write("\n")

    report["_tasks"] = tasks
    return report


# --------------------------------------------------------------------------- #
# CLI
# --------------------------------------------------------------------------- #
def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Symbolic planner: decompose goals into a dependency DAG and submit tasks."
    )
    parser.add_argument("--domain", default=DEFAULT_DOMAIN, help="operator/domain JSON file")
    parser.add_argument("--goal", default=DEFAULT_GOAL, help="goal/problem JSON file")
    parser.add_argument("--report", default=DEFAULT_REPORT, help="metrics report output path")
    parser.add_argument(
        "--plan-export", dest="plan_export", default=DEFAULT_EXPORT, help="plan DAG export path"
    )
    parser.add_argument("--kv-dir", default="kv", help="KV directory for --submit-mode kv")
    parser.add_argument(
        "--submit-mode",
        choices=["local", "kv", "tcp", "none"],
        default="local",
        help="how planned tasks are submitted",
    )
    parser.add_argument("--orchestrator", default="", help="host:port for --submit-mode tcp")
    parser.add_argument("--log", default=DEFAULT_LOG, help="submission log path")
    parser.add_argument("--max-expansions", type=int, default=200000)
    parser.add_argument("--quiet", action="store_true")
    return parser


def main(argv=None) -> int:
    args = build_parser().parse_args(argv)
    report = run_planner(
        domain_path=args.domain,
        goal_path=args.goal,
        report_path=args.report,
        export_path=args.plan_export,
        kv_dir=args.kv_dir,
        submit_mode=args.submit_mode,
        orchestrator=args.orchestrator,
        log_path=args.log,
        max_expansions=args.max_expansions,
    )
    report.pop("_tasks", None)
    if not args.quiet:
        sys.stdout.write(canonical_json(report) + "\n")
    return 0 if report["plan_success"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

